/* FitFirst V2 — Sessions. Merges the real console's "Stylist Client Dossiers" (filter chips with counts, handoff-code search,
   expandable session cards, log purchase / mark no purchase) with V1's live queue, so staff and owners use one page. */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES;
  const S = { view: null, filter: 'ALL', ch: '', q: '', days: 7, open: {}, page: 0 };
  const OUT = { WAITING: 'Waiting', ACTIVE: 'With staff', PURCHASED: 'Purchased', NO_PURCHASE: 'No purchase', LEFT: 'Left midway', ALL: 'All' };
  const bucket = (v) => (v.status === 'WAITING' ? 'WAITING' : ['ASSIGNED', 'TRYING'].includes(v.status) ? 'ACTIVE' : v.status === 'PURCHASED' ? 'PURCHASED' : v.status === 'BROWSING' ? 'BROWSING' : v.status === 'ABANDONED' ? 'LEFT' : 'NO_PURCHASE');
  const sum = (p) => (p ? [FF.TAX.depts[p.dept], (p.cats || []).map(FF.catName).join(', '), p.occasion ? FF.cap(p.occasion) : '', p.budget ? 'up to ' + FF.inr(p.budget) : ''].filter(Boolean).join(' · ') : 'Details erased at shopper’s request');
  const saleOf = (v) => v.sale && FF.db.sales.find((s) => s.id === v.sale);

  const lane = (title, list, tone) => `<div class="lane"><h3>${title} <span class="badge ${tone && list.length ? 'b-' + tone : ''}">${list.length}</span></h3>${list.map(card).join('') || `<div class="empty small" style="padding:24px 8px">Nothing here.</div>`}</div>`;
  const card = (v) => { const p = v.profiles[0], w = Date.now() - (v.waitingSince || v.at), s = saleOf(v); return `<div class="qcard ${v.status === 'WAITING' && w > 5 * 60000 ? 'urgent' : ''}"><div class="row between"><a class="code" style="font-size:17px;text-decoration:none" href="#/session/${v.code}">${v.code}</a><span class="small ${v.status === 'WAITING' && w > 5 * 60000 ? 'bad b' : 'muted'}">${v.status === 'WAITING' ? 'waiting ' + FF.ago(v.waitingSince || v.at) : s ? FF.inr(s.total) : esc(v.staff ? FF.staffName(v.staff) : '')}</span></div><div class="small">${esc(sum(p))}${v.profiles.length > 1 ? ` <span class="badge">+${v.profiles.length - 1} family</span>` : ''}</div><div class="row wrap gap6">${U.badge(FF.cap(v.channel.toLowerCase()))}${U.badge(v.shortlist.length + ' to try', v.shortlist.length ? 'brass' : '')}${v.lang && v.lang !== 'en' ? U.badge(v.lang === 'gu' ? 'ગુજરાતી' : 'हिन्दी', 'info') : ''}</div>${v.status === 'WAITING' ? `<button class="btn btn-p btn-s" data-act="v-claim" data-code="${v.code}">Claim — I’ll help</button>` : `<a class="btn btn-s" href="#/session/${v.code}">Open session</a>`}</div>`; };
  const dossier = (v) => { const p = v.profiles[0] || {}, s = saleOf(v), b = bucket(v), open = !!S.open[v.code], st = { WAITING: ['Waiting', 'warn'], ACTIVE: ['With ' + FF.staffName(v.staff), 'info'], PURCHASED: ['Purchased', 'ok'], NO_PURCHASE: ['No purchase', ''], LEFT: ['Left midway', ''], BROWSING: ['In progress', ''] }[b];
    return `<article class="dossier ${open ? 'open' : ''}"><div class="dh" data-act="s-toggle" data-code="${v.code}" role="button" tabindex="0" aria-expanded="${open}"><div><div class="code" style="font-size:16px">${v.code}</div><div class="tiny muted mono">${FF.fmtDT(v.at)}</div></div><div class="small" style="min-width:0"><div class="inkc b">${esc(sum(p))}</div><div class="muted tiny">${esc([Object.values(p.sizes || {}).filter(Boolean).join(', ') && 'Size ' + Object.values(p.sizes || {}).filter(Boolean).join(', '), p.tone ? 'Tone ' + p.tone : '', (p.goals || []).map((g) => FF.TAX.goals[g]).join(', ')].filter(Boolean).join(' · ') || 'No size or tone given')}</div></div>
      <div class="small hm"><span class="muted">${v.picks.length} shown · ${v.picks.filter((x) => ['tried', 'rejected', 'bought', 'bag'].includes(x.state)).length} tried</span>${s ? `<div class="b">${FF.inr(s.total)}</div>` : ''}</div>${U.badge(st[0], st[1])}<span class="muted">${FF.icon('down')}</span></div>
      ${open ? `<div class="db"><div class="row between wrap mt12 mb16"><span class="small muted">${esc(FF.cap(v.channel.toLowerCase()))} · ${v.staff ? 'with ' + esc(FF.staffName(v.staff)) : 'not claimed'}${v.noBuy ? ' · reason: ' + esc(v.noBuy) : ''}${v.holdout && R.MGR.includes(FF.me().role) ? ' · <span title="This visit is in the control group: no clearance nudge">control group</span>' : ''}</span><div class="row wrap gap6">${b === 'WAITING' ? `<button class="btn btn-s btn-p" data-act="v-claim" data-code="${v.code}">Claim</button>` : ''}${['WAITING', 'ACTIVE'].includes(b) ? `<button class="btn btn-s" data-act="v-nobuy" data-code="${v.code}">Mark no purchase</button><button class="btn btn-s" data-act="v-sale" data-code="${v.code}">Log purchase</button>` : ''}<a class="btn btn-s btn-p" href="#/session/${v.code}">Open session ${FF.icon('right')}</a></div></div>
        <div class="minis">${v.picks.slice(0, 7).map((pk) => { const pr = FF.prod(pk.pid); return pr ? `<div class="mini ${pk.state === 'bought' ? 'bought' : pk.state === 'rejected' ? 'rej' : ''}"><div class="gimg">${FF.garment(pr)}</div><div class="tiny"><b class="inkc">${esc(pr.name)}</b><br><span class="${pk.state === 'bought' ? 'ok b' : 'muted'}">${pk.state === 'bought' ? '✓ Bought' : pk.state === 'rejected' ? 'Rejected' : v.shortlist.includes(pk.pid) ? 'Wants to try' : '#' + pk.rank}</span></div></div>` : ''; }).join('') || '<p class="small muted">No pieces were shown.</p>'}</div></div>` : ''}</article>`; };

  const renderSessions = (view) => {
    const db = FF.db; S.view = view;
    const from = Date.now() - S.days * FF.DAY, inRange = db.visits.filter((v) => v.at >= from && v.status !== 'BROWSING');
    const cnt = { ALL: inRange.length }; const inCh = inRange.filter((v) => !S.ch || v.channel === S.ch); cnt.ALL = inCh.length; ['WAITING', 'ACTIVE', 'PURCHASED', 'NO_PURCHASE', 'LEFT'].forEach((k) => { cnt[k] = inCh.filter((v) => bucket(v) === k).length; });
    const q = S.q.toUpperCase().replace(/^FF-?/, '');
    const rows = db.visits.filter((v) => v.status !== 'BROWSING' && (q ? v.code.includes(q) : v.at >= from) && (S.filter === 'ALL' || bucket(v) === S.filter) && (!S.ch || v.channel === S.ch)).sort((a, b) => b.at - a.at);
    const per = 10, pages = Math.max(1, Math.ceil(rows.length / per)); S.page = Math.min(S.page, pages - 1); const slice = rows.slice(S.page * per, S.page * per + per);
    const t0 = new Date().setHours(0, 0, 0, 0), help = db.help.filter((h) => !h.done);
    return `<div class="ph1"><div><div class="eyebrow">Floor</div><h1 class="mt8">${view === 'board' ? 'Live queue' : 'Visits'}</h1><p>${view === 'board' ? 'Shoppers appear here the moment they finish on the kiosk, a tablet or their phone. Claim one, bring their pieces, mark what happened.' : 'Every consultation, searchable by the code the shopper shows you — not just the latest hundred.'}</p></div><div class="row wrap"><button class="btn" data-act="sim-walkin" title="Creates a finished consultation, as if a shopper just used the kiosk">${FF.icon('plus')} Simulate a walk-in</button></div></div>
      ${help.map((h) => `<div class="note n-bad row mb8"><span class="grow"><b>Help requested</b> · ${esc(h.where)}${h.text ? ' · ' + esc(h.text) : ''} · ${FF.ago(h.at)} ago</span><button class="btn btn-s" data-act="help-done" data-id="${h.id}">I’m on it</button></div>`).join('')}
      ${S.view === 'board' ? `<div class="cols">${lane('Waiting', db.visits.filter((v) => v.status === 'WAITING').sort((a, b) => (a.waitingSince || a.at) - (b.waitingSince || b.at)), 'warn')}${lane('With staff', db.visits.filter((v) => ['ASSIGNED', 'TRYING'].includes(v.status)), 'info')}${lane('Done today', db.visits.filter((v) => ['PURCHASED', 'NO_PURCHASE'].includes(v.status) && v.at >= t0).reverse().slice(0, 8), 'ok')}</div>`
      : `<div class="filters"><div style="position:relative;flex:1;min-width:220px;max-width:340px"><input type="search" placeholder="Search by handoff code, e.g. 7K2Q" value="${esc(S.q)}" data-change="s-q" aria-label="Search by handoff code" style="font-family:var(--mono);text-transform:uppercase"></div><div class="row wrap gap6">${Object.keys(OUT).filter((k) => k !== 'ALL').concat('ALL').map((k) => `<button class="chip" data-act="s-filter" data-v="${k}" aria-pressed="${S.filter === k}">${OUT[k]} <span class="mono tiny">${cnt[k]}</span></button>`).join('')}</div><select data-change="s-ch" aria-label="Channel" style="width:auto"><option value="">All channels</option>${['KIOSK', 'ASSISTED', 'QR'].map((c) => `<option value="${c}" ${S.ch === c ? 'selected' : ''}>${{ KIOSK: 'Kiosk', ASSISTED: 'Assisted tablet', QR: 'QR on phone' }[c]}</option>`).join('')}</select><span class="grow"></span>${U.seg('s-days', [[1, 'Today'], [7, '7 days'], [30, '30 days']], S.days)}</div>
        ${q ? `<p class="small mb8 ${rows.length ? 'ok' : 'bad'} b">${rows.length ? `${rows.length} session${rows.length > 1 ? 's' : ''} match “${esc(S.q.toUpperCase())}”` : `No session found for “${esc(S.q.toUpperCase())}”`}</p>` : ''}
        <div class="row between mb8"><span class="small muted">${rows.length} session${rows.length === 1 ? '' : 's'}${q ? '' : ' in this period'}</span><button class="link small" data-act="s-expand">${slice.every((v) => S.open[v.code]) && slice.length ? 'Collapse all' : 'Expand all'}</button></div>
        ${slice.map(dossier).join('') || `<div class="card">${U.empty('users', 'No sessions here', q ? 'Check the code with the shopper — it is on their screen or phone.' : 'Change the period or the filter.')}</div>`}
        ${rows.length > per ? `<div class="pager" style="border:0;padding:8px 0"><span>${S.page * per + 1}–${Math.min(rows.length, (S.page + 1) * per)} of ${rows.length}</span><span class="row gap6"><button class="btn btn-s" data-act="s-page" data-d="-1" ${S.page === 0 ? 'disabled' : ''}>Previous</button><button class="btn btn-s" data-act="s-page" data-d="1" ${S.page >= pages - 1 ? 'disabled' : ''}>Next</button></span></div>` : ''}`}`; };
  FF.page('queue', { title: 'Live queue', icon: 'users', roles: R.FLOOR, render: () => renderSessions('board') });
  FF.page('visits', { title: 'Visits', icon: 'list', roles: R.FLOOR, render: () => renderSessions('list') });
  FF.onChange('s-ch', (v) => { S.ch = v; S.page = 0; FF.render(); });
  FF.act('s-filter', (d) => { S.filter = d.v; S.page = 0; FF.render(); });
  FF.act('s-days', (d) => { S.days = +d.v; S.page = 0; FF.render(); });
  FF.act('s-page', (d) => { S.page += +d.d; FF.render(); window.scrollTo({ top: 0, behavior: 'smooth' }); });
  FF.act('s-toggle', (d) => { S.open[d.code] = !S.open[d.code]; FF.render(); });
  FF.act('s-expand', () => { const all = $$open(); const anyClosed = all.some((c) => !S.open[c]); all.forEach((c) => { S.open[c] = anyClosed; }); FF.render(); });
  const $$open = () => FF.$$('.dossier .dh').map((e) => e.dataset.code);
  FF.onChange('s-q', (v) => { S.q = v; S.page = 0; FF.render(); const i = $('.filters input[type=search]'); if (i) { i.focus(); i.setSelectionRange(v.length, v.length); } });
  document.addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('.dh[data-act]')) { e.preventDefault(); e.target.click(); } });
})();
